#!/usr/bin/env node
// Generated by OrchestKit Claude Plugin
// Created: 2026-10-08
/**
 * The docs Playwright install can never hang the required Docs Site Build (#4665).
 *
 * THE FAILURE
 *
 *   `npx playwright install --with-deps chromium` hung three times on
 *   2026-10-07 (jobs 112950356919, 112961977648, 113017086059) until the job
 *   was cancelled at about 21 minutes. All three stopped in the SAME place,
 *   before any browser download: the `--with-deps` apt update. The Azure
 *   Ubuntu mirror stopped answering, apt fell back to archive.ubuntu.com, and
 *   the log went silent for 20 minutes after `noble-security InRelease`.
 *
 * THE INVARIANT, per arm
 *
 *   cache:    ~/.cache/ms-playwright is cached under a key that names the
 *             installed Playwright version, so a hit skips the download.
 *   no-combo: no step runs the unbounded `playwright install --with-deps`.
 *   apt:      apt gets network timeouts before the system-deps step, so a
 *             dead mirror fails in seconds instead of stalling.
 *   bounded:  every step that runs `playwright install` (browser or deps)
 *             has timeout-minutes of at most 5 and retries once, each
 *             attempt under its own `timeout`.
 *   cache-bounded: the ms-playwright cache step has timeout-minutes of at
 *             most 5 and sets SEGMENT_DOWNLOAD_TIMEOUT_MINS below that cap,
 *             so a stalled restore cannot sit on the action's 10 minute
 *             default segment timeout (#4670). Not proven: whether the
 *             step timeout also covers the post-step cache save.
 *   lock-wait: the install-deps step waits for every apt-get and dpkg to
 *             exit before its retry, and names the dpkg lock holder when it
 *             gives up (#4923). `timeout` stops npx but not the root apt-get
 *             it started under sudo, so attempt 1's orphan kept the dpkg lock
 *             past attempt 2's 120 s DPkg::Lock::Timeout (run 40229660456).
 *   slow-mirror: that wait outlasts a crawling mirror, so install-deps alone
 *             has up to 10 minutes. A live apt-get is still making progress,
 *             and the 240 s wait gave up on two orphans still fetching, runs
 *             42214992662 and 42215416026. The attempt budget stays inside
 *             the step, so the retry still runs before timeout-minutes kills it.
 *   offline:  a normal run never touches the apt mirror. On 2026-11-11 the
 *             runner could not resolve archive.ubuntu.com, and Docs Site Build
 *             failed twice on two PRs (runs 43053876278 and its rerun) in
 *             `apt-get update`, before any package was fetched. On the
 *             ubuntu-26.04 image install-deps only adds 9 font packages
 *             (run 43063535095); every library Chromium links is already
 *             there. So the cached Chromium is installed first, one launch is
 *             tried, and the apt steps run only when that launch fails.
 */
import { readFileSync } from 'node:fs';
import { createRequire } from 'node:module';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..', '..');
// js-yaml is a declared dependency of src/hooks, and the CI job that runs
// tests/ci installs src/hooks deps only. The root package.json has no YAML
// parser, so resolve from src/hooks, not from the root.
const require = createRequire(join(ROOT, 'src/hooks/package.json'));
const yaml = require('js-yaml');

const wf = yaml.load(readFileSync(join(ROOT, '.github/workflows/docs.yml'), 'utf8'));
const failures = [];
const fail = (arm, msg) => failures.push(`${arm}: ${msg}`);

// The job that runs the docs Playwright e2e.
const job = Object.values(wf.jobs).find((j) =>
  (j.steps || []).some((s) => /playwright test/.test(s.run || '')),
);
if (!job) {
  console.error('FAIL: no docs.yml job runs `playwright test`; the scan is broken');
  process.exit(1);
}
const steps = job.steps;
const runOf = (s) => String(s.run || '');

// cache
const cache = steps.find(
  (s) => /^actions\/cache@/.test(String(s.uses || '')) && /ms-playwright/.test(String(s.with?.path || '')),
);
if (!cache) fail('cache', 'no actions/cache step for ~/.cache/ms-playwright');
else if (!/playwright/i.test(String(cache.with?.key || '')) || !/\$\{\{\s*steps\.[\w-]+\.outputs\.version\s*\}\}/.test(String(cache.with?.key || ''))) {
  fail('cache', `cache key does not name the Playwright version: ${cache.with?.key}`);
}

// cache-bounded
if (cache) {
  const tm = Number(cache['timeout-minutes']);
  if (!(tm >= 1 && tm <= 5)) {
    fail('cache-bounded', `cache step "${cache.name}" has timeout-minutes ${cache['timeout-minutes']}, want 1 to 5`);
  }
  if (cache['continue-on-error'] !== true) {
    fail('cache-bounded', `cache step "${cache.name}" must set continue-on-error: true, so a timed-out restore is a miss, not a red job`);
  }
  const seg = Number(cache.env?.SEGMENT_DOWNLOAD_TIMEOUT_MINS);
  if (!(seg >= 1 && (!(tm > 0) || seg < tm))) {
    fail(
      'cache-bounded',
      `cache step "${cache.name}" env SEGMENT_DOWNLOAD_TIMEOUT_MINS is ${cache.env?.SEGMENT_DOWNLOAD_TIMEOUT_MINS}, want 1 or more and below timeout-minutes`,
    );
  }
}

// no-combo
for (const s of steps) {
  if (/playwright install[^\n]*--with-deps/.test(runOf(s))) fail('no-combo', `step "${s.name}" still runs install --with-deps`);
}

// apt
const depsIdx = steps.findIndex((s) => /playwright install-deps/.test(runOf(s)));
const aptIdx = steps.findIndex((s) => /Acquire::https?::Timeout/.test(runOf(s)));
if (depsIdx === -1) fail('apt', 'no `playwright install-deps` step');
else if (aptIdx === -1 || aptIdx > depsIdx) fail('apt', 'apt network timeouts are not set before install-deps');

// bounded
const installs = steps.filter((s) => /playwright install/.test(runOf(s)));
if (installs.length === 0) fail('bounded', 'no playwright install step found');
for (const s of installs) {
  const tm = Number(s['timeout-minutes']);
  const cap = /playwright install-deps/.test(runOf(s)) ? 10 : 5; // see slow-mirror
  if (!(tm > 0 && tm <= cap)) fail('bounded', `step "${s.name}" has timeout-minutes ${s['timeout-minutes']}, want 1 to ${cap}`);
  if (!/for attempt in 1 2\b/.test(runOf(s))) fail('bounded', `step "${s.name}" does not retry once`);
  // A quoted variable is allowed: install-deps sizes attempt 2 from what the
  // step budget leaves (#4923); timeout-minutes above still caps the step.
  if (!/\btimeout (\d+|"\$\w+") npx playwright install/.test(runOf(s))) fail('bounded', `step "${s.name}" has no per-attempt timeout`);
}

// lock-wait
if (depsIdx !== -1) {
  const deps = runOf(steps[depsIdx]);
  if (!/\bps\b[^\n]*-C apt-get,dpkg/.test(deps)) {
    fail('lock-wait', `step "${steps[depsIdx].name}" does not look for apt-get and dpkg before its retry`);
  }
  if (!/fuser[^\n]*\/var\/lib\/dpkg\/lock-frontend/.test(deps)) {
    fail('lock-wait', `step "${steps[depsIdx].name}" does not name the dpkg lock holder when it gives up`);
  }

  // slow-mirror
  const wait = Number(deps.match(/"\$SECONDS" -lt (\d+)/)?.[1]);
  const budget = Number(deps.match(/left=\$\(\((\d+) - SECONDS\)\)/)?.[1]);
  const stepSeconds = Number(steps[depsIdx]['timeout-minutes']) * 60;
  if (!(wait >= 480)) fail('slow-mirror', `the wait for apt-get to exit is ${wait} s, want at least 480`);
  if (!(budget >= wait + 60 && budget < stepSeconds)) {
    fail('slow-mirror', `attempt budget ${budget} s must leave attempt 2 at least 60 s after the ${wait} s wait and stay under the ${stepSeconds} s step`);
  }
}

// offline
const browserIdx = steps.findIndex((s) => /playwright install chromium/.test(runOf(s)));
const probeIdx = steps.findIndex((s) => /chromium\.launch\(/.test(runOf(s)));
const probe = steps[probeIdx];
if (probeIdx === -1) {
  fail('offline', 'no step tries a Chromium launch before reaching for apt');
} else {
  if (!probe.id) fail('offline', `launch step "${probe.name}" has no id, so later steps cannot read its result`);
  if (browserIdx === -1 || browserIdx > probeIdx) fail('offline', 'the launch is tried before Chromium is installed');
  const gated = (s) => probe.id && new RegExp(`steps\\.${probe.id}\\.outputs\\.`).test(String(s.if || ''));
  for (const [idx, what] of [[aptIdx, 'apt network timeouts'], [depsIdx, 'install-deps']]) {
    if (idx === -1) continue;
    if (idx < probeIdx) fail('offline', `${what} step "${steps[idx].name}" runs before the launch is tried`);
    if (!gated(steps[idx])) fail('offline', `${what} step "${steps[idx].name}" runs on every build; its if must read steps.${probe.id}.outputs`);
  }
}

if (failures.length) {
  for (const f of failures) console.error(`FAIL ${f}`);
  process.exit(1);
}
console.log(`PASS: docs Playwright install is cached and bounded (${installs.length} install steps)`);
